BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '15s';
SET LOCAL lock_timeout = '3s';
SELECT json_build_object('kind','context','database',current_database(),'role',current_user,'read_only',current_setting('transaction_read_only'),'at',CURRENT_TIMESTAMP);
WITH expected(name) AS (VALUES ('append_security_event'),('block_security_event_mutation'),('audit_document_version_lifecycle'),('audit_content_source_change'),('enqueue_security_event_for_siem'),('claim_siem_deliveries'),('complete_siem_delivery'),('fail_siem_delivery'),('get_siem_delivery_health'))
SELECT json_build_object('kind','function','name',e.name,'present',p.oid IS NOT NULL,'signature',p.oid::regprocedure::text,'security_definer',p.prosecdef,'settings',p.proconfig,'definition',CASE WHEN p.oid IS NOT NULL THEN pg_get_functiondef(p.oid) END)
FROM expected e LEFT JOIN pg_proc p ON p.proname=e.name AND p.pronamespace='public'::regnamespace ORDER BY e.name;
SELECT json_build_object('kind','trigger','table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('security_events','document_versions','content_sources') AND NOT t.tgisinternal ORDER BY c.relname,t.tgname;
SELECT json_build_object('kind','table','name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rowsecurity',c.relrowsecurity) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('security_events','siem_delivery_outbox') ORDER BY c.relname;
COMMIT;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '15s';
SELECT json_build_object('kind','role','name',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls) FROM pg_roles WHERE rolname='postgres';
SELECT json_build_object('kind','privileges','table',n,'role','postgres','owner',pg_get_userbyid(c.relowner),'update',has_table_privilege('postgres',c.oid,'UPDATE'),'delete',has_table_privilege('postgres',c.oid,'DELETE'),'truncate',has_table_privilege('postgres',c.oid,'TRUNCATE')) FROM (VALUES('security_events'),('siem_delivery_outbox')) AS e(n) JOIN pg_class c ON c.oid=to_regclass('public.'||n);
COMMIT;
